using System.Reflection;
using DaedalusStudio.Projects.Protocol;
using DaedalusStudio.Rpc;
using DaedalusStudio.TextTemplating.Protocol;
using DaedalusStudio.Workbench.Build;
using DaedalusStudio.Workbench.CustomTools;
using DaedalusStudio.Workbench.Output;
using DaedalusStudio.Workbench.Projects;

namespace DaedalusStudio.Projects.Tests;

/// <summary>
/// Custom tools (ADR 0035): the ResX generator's class (in StronglyTypedResourceBuilder's shape), text templates through
/// the real T4 host, and both run on samples/ProjectSystem's Items project, whose generated files then compile.
/// </summary>
public sealed class CustomToolIntegrationTests : IAsyncLifetime
{
    private static readonly TimeSpan s_timeout = TimeSpan.FromMinutes(3);
    private readonly string _root = Path.Combine(DaedalusStudio.Platform.RealPath.Resolve(Path.GetTempPath()), "daedalus-customtools-" + Guid.NewGuid().ToString("N"));
    private SolutionService _solutions = null!;
    private TextTemplatingService _templates = null!;

    private string ItemsDir => Path.Combine(_root, "ProjectSystem", "src", "Items");

    private string ItemsProject => Path.Combine(ItemsDir, "Items.csproj");

    internal static string T4HostPath =>
        Environment.GetEnvironmentVariable(TextTemplatingHostLaunch.EnvironmentVariable) is { Length: > 0 } host ? host
        : Path.Combine(BuildHostIntegrationTests.RepoRoot, "src", "DaedalusStudio.TextTemplating.Host", "bin", Configuration, "net10.0", "daedalus-t4host.dll");

    private static string Configuration =>
        typeof(CustomToolIntegrationTests).Assembly.GetCustomAttributes<AssemblyMetadataAttribute>().Single(a => a.Key == "DaedalusConfiguration").Value!;

    private static CancellationToken Timeout() =>
        CancellationTokenSource.CreateLinkedTokenSource(TestContext.Current.CancellationToken, new CancellationTokenSource(s_timeout).Token).Token;

    public ValueTask InitializeAsync()
    {
        Copy(Path.Combine(BuildHostIntegrationTests.RepoRoot, "samples", "ProjectSystem"), Path.Combine(_root, "ProjectSystem"));
        File.WriteAllText(Path.Combine(_root, "Directory.Build.props"), "<Project />");
        DaedalusStudio.Tests.FixtureSdk.Pin(_root);
        File.WriteAllText(Path.Combine(_root, "Directory.Packages.props"), "<Project><PropertyGroup><ManagePackageVersionsCentrally>false</ManagePackageVersionsCentrally></PropertyGroup></Project>");
        _solutions = new SolutionService(() => BuildHostIntegrationTests.HostAssemblyPath);
        _solutions.Log += (_, line) => Console.Error.WriteLine("[host] " + line);
        Assert.True(File.Exists(T4HostPath), "T4 host not built: " + T4HostPath);
        _templates = new TextTemplatingService(() => ProcessLaunchInfo.FromPath(T4HostPath));
        _templates.Log += (_, line) => Console.Error.WriteLine("[t4host] " + line);
        return ValueTask.CompletedTask;
    }

    public async ValueTask DisposeAsync()
    {
        await _templates.DisposeAsync();
        await _solutions.DisposeAsync();
        try
        {
            Directory.Delete(_root, recursive: true);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
        }
    }

    private static void Copy(string source, string target)
    {
        Directory.CreateDirectory(target);
        foreach (var file in Directory.EnumerateFiles(source))
        {
            File.Copy(file, Path.Combine(target, Path.GetFileName(file)));
        }

        foreach (var directory in Directory.EnumerateDirectories(source).Where(d => Path.GetFileName(d) is not ("bin" or "obj")))
        {
            Copy(directory, Path.Combine(target, Path.GetFileName(directory)));
        }
    }

    [Fact]
    public void The_ResX_generator_writes_a_strongly_typed_class()
    {
        var resx = File.ReadAllText(Path.Combine(ItemsDir, "Resources.resx"));
        Assert.Equal(["Title", "Farewell"], ResXGenerator.Read(resx).Select(r => r.Name));

        var code = ResXGenerator.Generate(resx, "Resources", "Fixture.Items", "Fixture.Items.Resources", isPublic: false).ReplaceLineEndings("\n");
        Assert.StartsWith("//------------------------------------------------------------------------------\n// <auto-generated>", code, StringComparison.Ordinal);
        Assert.Contains("namespace Fixture.Items {", code, StringComparison.Ordinal);
        Assert.Contains("    internal class Resources {", code, StringComparison.Ordinal);
        Assert.Contains("new global::System.Resources.ResourceManager(\"Fixture.Items.Resources\", typeof(Resources).Assembly);", code, StringComparison.Ordinal);
        Assert.Contains("///   Looks up a localized string similar to Goodbye.", code, StringComparison.Ordinal);
        Assert.Contains("        internal static string Farewell {", code, StringComparison.Ordinal);
        Assert.True(code.IndexOf("Farewell {", StringComparison.Ordinal) < code.IndexOf("Title {", StringComparison.Ordinal), "properties in name order");

        // Public, escaped values, non-string resources, identifiers.
        const string Extra = """
            <root>
              <data name="1st item" xml:space="preserve"><value>a &lt;b&gt; &amp; c</value></data>
              <data name="Icon" type="System.Resources.ResXFileRef, System.Windows.Forms"><value>icon.png;System.Drawing.Bitmap, System.Drawing</value></data>
            </root>
            """;
        code = ResXGenerator.Generate(Extra, "Strings", string.Empty, "Strings", isPublic: true).ReplaceLineEndings("\n");
        Assert.DoesNotContain("namespace", code, StringComparison.Ordinal);
        Assert.Contains("public static string _1st_item {", code, StringComparison.Ordinal);
        Assert.Contains("similar to a &lt;b&gt; &amp; c.", code, StringComparison.Ordinal);
        Assert.Contains("public static global::System.Drawing.Bitmap Icon {", code, StringComparison.Ordinal);
        Assert.Equal("Root.Sub_Folder.Strings", ResXGenerator.ManifestResourceName("Root", _root, Path.Combine(_root, "Sub Folder", "Strings.resx")));
    }

    [Fact]
    public async Task Text_templates_run_in_the_T4_host_with_includes_and_report_errors()
    {
        var template = Path.Combine(ItemsDir, "Greeting.tt");
        var result = await _templates.TransformAsync(new T4TransformParams(template, null, "Fixture.Items"), Timeout());
        Assert.Empty(result.Diagnostics);
        Assert.Equal(".cs", result.Extension);
        Assert.Equal(File.ReadAllText(Path.Combine(ItemsDir, "Greeting.cs")).ReplaceLineEndings("\n").Trim(), result.Output!.ReplaceLineEndings("\n").Trim());

        // The content can come from the editor (unsaved), and the output directive sets the extension.
        result = await _templates.TransformAsync(new T4TransformParams(template, "<#@ output extension=\".txt\" #>\nHello <#= 6 * 7 #>", null), Timeout());
        Assert.Equal(".txt", result.Extension);
        Assert.Equal("Hello 42", result.Output!.Trim());

        // A compile error in the template: no output, the error with its line.
        result = await _templates.TransformAsync(new T4TransformParams(template, "line one\nline two\nline three\n<# int x = \"text\"; #>\n", null), Timeout());
        Assert.Null(result.Output);
        var error = Assert.Single(result.Diagnostics, d => !d.IsWarning);
        Assert.True(error.Line == 4 && error.Column == 10, string.Join("; ", result.Diagnostics.Select(d => $"{d.File}({d.Line},{d.Column}) {d.Message}")));
        Assert.True(_templates.IsRunning);

        // A template the parser rejects (an unclosed block): its error, once.
        result = await _templates.TransformAsync(new T4TransformParams(template, "one\n<# unclosed", null), Timeout());
        Assert.Null(result.Output);
        Assert.Single(result.Diagnostics, d => !d.IsWarning);

        // A host that dies is started again for the next template.
        var pid = _templates.ProcessId!.Value;
        System.Diagnostics.Process.GetProcessById(pid).Kill();
        await Task.Delay(500, TestContext.Current.CancellationToken);
        result = await _templates.TransformAsync(new T4TransformParams(template, "ok", null), Timeout());
        Assert.Equal("ok", result.Output?.Trim());
    }

    [Fact]
    public async Task Custom_tools_regenerate_the_Items_project_files_which_then_build()
    {
        var output = new OutputService();
        var builds = new BuildService(_solutions, output) { Options = () => new BuildOptions { UpToDateCheck = false } };
        var tools = new CustomToolService(new ProjectItemService(_solutions), _templates);
        await _solutions.OpenAsync(ItemsProject, trusted: true, restore: false, Timeout());
        var deadline = DateTime.UtcNow + s_timeout;
        while (_solutions.Progress is not { Completed: true } || _solutions.Projects.Count != 1)
        {
            Assert.True(DateTime.UtcNow < deadline, "Timed out.");
            await Task.Delay(25, TestContext.Current.CancellationToken);
        }

        // ResX: a new resource, a regenerated class; the project file keeps (or gets) its metadata.
        var resx = Path.Combine(ItemsDir, "Resources.resx");
        File.WriteAllText(resx, File.ReadAllText(resx).Replace("</root>", "  <data name=\"Welcome\" xml:space=\"preserve\">\n    <value>Welcome!</value>\n  </data>\n</root>", StringComparison.Ordinal));
        var generated = await tools.RunAsync(ItemsProject, resx, ResXGenerator.Internal, "Fixture.Items", "Fixture.Items", trusted: true, Timeout());
        Assert.True(generated.Succeeded, string.Join("; ", generated.Diagnostics.Select(d => d.Message)));
        Assert.Equal(Path.Combine(ItemsDir, "Resources.Designer.cs"), generated.Output);
        Assert.Contains("internal static string Welcome {", File.ReadAllText(generated.Output!), StringComparison.Ordinal);

        // T4: another name, and the generated class.
        var include = Path.Combine(ItemsDir, "Names.ttinclude");
        File.WriteAllText(include, File.ReadAllText(include).Replace("\"Grace\"", "\"Grace\", \"Linus\"", StringComparison.Ordinal));
        generated = await tools.RunAsync(ItemsProject, Path.Combine(ItemsDir, "Greeting.tt"), CustomToolService.TextTemplating, "Fixture.Items", "Fixture.Items", trusted: true, Timeout());
        Assert.True(generated.Succeeded, string.Join("; ", generated.Diagnostics.Select(d => d.Message)));
        Assert.Contains("public const string Linus = \"Hello, Linus\";", File.ReadAllText(Path.Combine(ItemsDir, "Greeting.cs")), StringComparison.Ordinal);

        // Templates don't run untrusted.
        var refused = await tools.RunAsync(ItemsProject, Path.Combine(ItemsDir, "Greeting.tt"), CustomToolService.TextTemplating, "Fixture.Items", "Fixture.Items", trusted: false, Timeout());
        Assert.False(refused.Succeeded);
        Assert.Contains("trusted", refused.Diagnostics[0].Message, StringComparison.Ordinal);

        // A new generator on a new file: the project file gets Generator's partner metadata as Visual Studio writes it.
        var strings = Path.Combine(ItemsDir, "Strings.resx");
        File.WriteAllText(strings, "<root>\n  <data name=\"Hi\" xml:space=\"preserve\">\n    <value>Hi</value>\n  </data>\n</root>\n");
        await _solutions.ReevaluateAsync(ItemsProject, Timeout());
        generated = await tools.RunAsync(ItemsProject, strings, ResXGenerator.Public, "Fixture.Items", "Fixture.Items", trusted: true, Timeout());
        Assert.True(generated.Succeeded);
        var project = File.ReadAllText(ItemsProject).ReplaceLineEndings("\n");
        Assert.Contains("<LastGenOutput>Strings.Designer.cs</LastGenOutput>", project, StringComparison.Ordinal);
        Assert.Contains("<Compile Update=\"Strings.Designer.cs\">", project, StringComparison.Ordinal);
        Assert.Contains("<DependentUpon>Strings.resx</DependentUpon>", project, StringComparison.Ordinal);

        // Everything generated compiles.
        var result = await builds.BuildAsync(BuildTargets.Build, null, Timeout());
        Assert.True(result.Succeeded, builds.Channel.GetText());
    }
}
